package tui

import (
	"bufio"
	"encoding/json"
	"os"
	"runtime"
	"strconv"
	"strings"
	"testing"
	"time"
)

// The golden file is generated by driving the upstream Editor with scripted
// input sequences and dumping the text, cursor, render, and expanded text.
// See tui/testdata/editor_corpus.json.

type editorGolden struct {
	values map[string]string
}

func loadEditorGolden(t *testing.T) *editorGolden {
	t.Helper()
	file, err := os.Open("testdata/editor_golden.txt")
	if err != nil {
		t.Fatalf("open golden: %v", err)
	}
	defer file.Close()
	values := map[string]string{}
	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		parts := strings.SplitN(line, " => ", 2)
		if len(parts) != 2 {
			t.Fatalf("bad golden line %q", line)
		}
		values[strings.TrimPrefix(parts[0], "ed ")] = parts[1]
	}
	if err := scanner.Err(); err != nil {
		t.Fatalf("scan: %v", err)
	}
	return &editorGolden{values: values}
}

type editorSpec struct {
	Text     *string  `json:"text"`
	Inputs   []string `json:"inputs"`
	Width    int      `json:"width"`
	Rows     int      `json:"rows"`
	History  []string `json:"history"`
	Focused  bool     `json:"focused"`
	Expanded bool     `json:"expanded"`
	Options  *struct {
		PaddingX               int `json:"paddingX"`
		AutocompleteMaxVisible int `json:"autocompleteMaxVisible"`
	} `json:"options"`
}

type editorHost struct {
	rows int
}

func (h *editorHost) Rows() int                { return h.rows }
func (h *editorHost) RequestRender(force bool) {}

func editorTestTheme() EditorTheme {
	return EditorTheme{
		BorderColor: mdTag("bc"),
		SelectList: SelectListTheme{
			SelectedPrefix: mdTag("sp"),
			SelectedText:   mdTag("st"),
			Description:    mdTag("sd"),
			ScrollInfo:     mdTag("si"),
			NoMatch:        mdTag("sn"),
		},
	}
}

// TestEditorAgainstUpstreamGolden replays the upstream editor corpus.
func TestEditorAgainstUpstreamGolden(t *testing.T) {
	golden := loadEditorGolden(t)
	data, err := os.ReadFile("testdata/editor_corpus.json")
	if err != nil {
		t.Fatalf("read corpus: %v", err)
	}
	corpus := map[string]editorSpec{}
	if err := json.Unmarshal(data, &corpus); err != nil {
		t.Fatalf("parse corpus: %v", err)
	}

	labels := make([]string, 0, len(corpus))
	for label := range corpus {
		labels = append(labels, label)
	}
	sortStrings(labels)

	for _, label := range labels {
		spec := corpus[label]
		rows := spec.Rows
		if rows == 0 {
			rows = 10
		}
		host := &editorHost{rows: rows}
		options := EditorOptions{}
		if spec.Options != nil {
			options.PaddingX = spec.Options.PaddingX
			options.AutocompleteMaxVisible = spec.Options.AutocompleteMaxVisible
		}
		editor := NewEditor(host, editorTestTheme(), options)
		editor.SetFocused(spec.Focused)
		for _, entry := range spec.History {
			editor.AddToHistory(entry)
		}
		if spec.Text != nil {
			editor.SetText(*spec.Text)
		}
		for _, input := range spec.Inputs {
			switch {
			case strings.HasPrefix(input, "MOUSE:"):
				parts := strings.Split(input, ":")
				x, _ := strconv.Atoi(parts[1])
				y, _ := strconv.Atoi(parts[2])
				width, _ := strconv.Atoi(parts[3])
				editor.HandleMouse(TuiMouseEvent{
					Type: MouseClick, Button: MouseButtonLeft,
					X: x, Y: y, Width: width, Height: 10, ScreenX: x, ScreenY: y,
				})
			case strings.HasPrefix(input, "SETTEXT:"):
				editor.SetText(input[len("SETTEXT:"):])
			default:
				editor.HandleInput(input)
			}
		}

		width := spec.Width
		if width == 0 {
			width = 30
		}
		checkGolden(t, golden.values, label+" text", mustJSON(editor.GetText()))
		// Upstream cursors are UTF-16 code-unit offsets; the Go port uses byte
		// offsets (divergence D61), so the golden cursor is translated.
		wantCursor, ok := golden.values[label+" cursor"]
		if !ok {
			t.Fatalf("missing golden %q", label+" cursor")
		}
		cursorParts := strings.Split(wantCursor, ",")
		wantLine, _ := strconv.Atoi(cursorParts[0])
		wantColJS, _ := strconv.Atoi(cursorParts[1])
		line, col := editor.Cursor()
		lines := editor.GetLines()
		wantCol := wantColJS
		if wantLine >= 0 && wantLine < len(lines) {
			wantCol = jsOffsetToByteOffset(lines[wantLine], wantColJS)
		}
		if line != wantLine || col != wantCol {
			t.Fatalf("%s cursor: got %d,%d want %d,%d", label, line, col, wantLine, wantCol)
		}
		checkGolden(t, golden.values, label+" render@"+strconv.Itoa(width), normalizeSlice(editor.Render(width)))
		if spec.Expanded {
			checkGolden(t, golden.values, label+" expanded", mustJSON(editor.GetExpandedText()))
		}
	}
}

// normalizeSlice converts a nil slice into an empty one so JSON output matches
// upstream's empty arrays.
func normalizeSlice(lines []string) []string {
	if lines == nil {
		return []string{}
	}
	return lines
}

// Upstream measures a large paste in UTF-16 code units (String.length), so
// astral characters count as two.
func TestEditorPasteThresholdCountsUTF16Units(t *testing.T) {
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	// 600 astral runes are 1200 UTF-16 units (> 1000) but only 600 runes.
	editor.handlePasteLocked(strings.Repeat("\U0001F600", 600))
	if got := editor.GetText(); !strings.Contains(got, "chars]") {
		t.Fatalf("paste was not collapsed to a marker: %q", got)
	}
}

// Mirrors first-occurrence start-marker removal in
// packages/tui/src/components/editor.ts, including an embedded marker that
// leaves its preceding bytes in the paste buffer.
func TestEditorBracketedPasteWithEmbeddedStartMarkerPreservesPrefix(t *testing.T) {
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	editor.HandleInput("prefix\x1b[200~payload\x1b[201~")
	if got, want := editor.GetText(), "prefixpayload"; got != want {
		t.Fatalf("pasted text = %q, want %q", got, want)
	}
}

func TestEditorBracketedLargePasteAvoidsCopyingInput(t *testing.T) {
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	pasted := strings.Repeat("plain text ", 24*1024)
	input := "\x1b[200~" + pasted + "\x1b[201~"

	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	editor.HandleInput(input)
	runtime.ReadMemStats(&after)

	if got := editor.GetExpandedText(); got != pasted {
		t.Fatalf("expanded paste length = %d, want %d", len(got), len(pasted))
	}
	allocated := after.TotalAlloc - before.TotalAlloc
	t.Logf("bracketed %d-byte input allocated %d bytes", len(input), allocated)
	if allocated > uint64(len(input))/4 {
		t.Fatalf("bracketed paste of %d bytes allocated %d bytes, want less than %d", len(input), allocated, len(input)/4)
	}
}

func TestEditorPasteFiltersControlBytesAndDecodesCSIu(t *testing.T) {
	// Port of packages/tui/src/components/editor.ts handlePaste.
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	editor.handlePasteLocked("a\x00b\r\nc\x1b[106;5uX\x1f")
	if got, want := editor.GetText(), "ab\nc\nX"; got != want {
		t.Fatalf("pasted text = %q, want %q", got, want)
	}
}

func TestEditorCleanLargePasteDoesNotCopyFilteredText(t *testing.T) {
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	pasted := strings.Repeat("plain text ", 24*1024)

	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	editor.handlePasteLocked(pasted)
	runtime.ReadMemStats(&after)

	if got := editor.GetExpandedText(); got != pasted {
		t.Fatalf("expanded paste length = %d, want %d", len(got), len(pasted))
	}
	allocated := after.TotalAlloc - before.TotalAlloc
	t.Logf("clean %d-byte paste allocated %d bytes", len(pasted), allocated)
	if allocated > uint64(len(pasted))/4 {
		t.Fatalf("clean %d-byte paste allocated %d bytes, want less than %d", len(pasted), allocated, len(pasted)/4)
	}
}

// TestEditorSubmitReentrancy: the submit handler runs outside the
// editor lock, so it may call back into the editor without deadlocking.
func TestEditorSubmitReentrancy(t *testing.T) {
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	var submitted []string
	editor.OnSubmit = func(text string) {
		submitted = append(submitted, text)
		// The interactive submit handler clears and reads the editor.
		editor.SetText("")
		_ = editor.GetText()
		editor.AddToHistory(text)
	}

	done := make(chan struct{})
	go func() {
		defer close(done)
		editor.SetText("hello")
		editor.HandleInput("\r")
	}()

	select {
	case <-done:
	case <-time.After(2 * time.Second):
		t.Fatal("HandleInput deadlocked in OnSubmit")
	}
	if len(submitted) != 1 || submitted[0] != "hello" {
		t.Fatalf("submitted = %v", submitted)
	}
	if editor.GetText() != "" {
		t.Fatalf("editor = %q", editor.GetText())
	}
}

// Mirrors packages/tui/src/word-navigation.ts: backward movement skips a
// contiguous punctuation run when the cursor is at its end.
func TestFindWordBackwardPunctuationRunDoesNotCopySegments(t *testing.T) {
	const segmentCount = 8192
	text := strings.Repeat("!", segmentCount)
	segments := make([]editorSegment, segmentCount)
	for index := range segments {
		segments[index] = editorSegment{Segment: "!", Index: index}
	}

	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	got := findWordBackwardSegments(text, len(text), segments)
	runtime.ReadMemStats(&after)

	if got != 0 {
		t.Fatalf("cursor = %d, want 0", got)
	}
	allocated := after.TotalAlloc - before.TotalAlloc
	t.Logf("backward navigation across %d segments allocated %d bytes", segmentCount, allocated)
	if allocated > uint64(segmentCount*4) {
		t.Fatalf("backward navigation across %d segments allocated %d bytes, want less than %d", segmentCount, allocated, segmentCount*4)
	}
}

// Mirrors packages/tui/src/word-navigation.ts findWordBackward: a word-like
// segment with punctuation leaves the cursor after its last punctuation rune.
func TestEditorWordNavigationDoesNotCopyRuneTables(t *testing.T) {
	text := "word." + strings.Repeat("x", 64*1024)
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	editor.SetText(text)
	editor.state.cursorCol = len(text)

	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	editor.moveWordBackwardsLocked()
	runtime.ReadMemStats(&after)

	if editor.state.cursorCol != len("word.") {
		t.Fatalf("cursor = %d, want %d", editor.state.cursorCol, len("word."))
	}
	allocated := after.TotalAlloc - before.TotalAlloc
	t.Logf("word navigation over %d bytes allocated %d bytes", len(text), allocated)
	if allocated > uint64(len(text))*2 {
		t.Fatalf("word navigation over %d bytes allocated %d bytes, want less than %d", len(text), allocated, len(text)*2)
	}
}

// The punctuation offset is a byte index, while the suffix may be UTF-8.
func TestFindWordBackwardAfterPunctuationAvoidsRuneSlice(t *testing.T) {
	text := "word." + strings.Repeat("x", 64*1024)
	segments := []editorSegment{{Segment: text, IsWordLike: true}}

	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	got := findWordBackwardSegments(text, len(text), segments)
	runtime.ReadMemStats(&after)

	if got != len("word.") {
		t.Fatalf("cursor = %d, want %d", got, len("word."))
	}
	unicodeText := "word.漢字"
	unicodeSegments := []editorSegment{{Segment: unicodeText, IsWordLike: true}}
	if got, want := findWordBackwardSegments(unicodeText, len(unicodeText), unicodeSegments), len("word."); got != want {
		t.Fatalf("Unicode cursor = %d, want %d", got, want)
	}
	allocated := after.TotalAlloc - before.TotalAlloc
	t.Logf("word movement over %d bytes allocated %d bytes", len(text), allocated)
	if allocated > uint64(len(text))/8 {
		t.Fatalf("word movement over %d bytes allocated %d bytes, want less than %d", len(text), allocated, len(text)/8)
	}
}

// The segmenter marks "e.g" word-like (its mid-word dot merges); the editor's
// word movement must use that flag, not recompute from the characters.
func TestEditorWordBackwardOverDottedWord(t *testing.T) {
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	editor.SetText("e.g.")
	editor.state.cursorCol = len("e.g.")
	editor.moveWordBackwardsLocked()
	if editor.state.cursorCol != 3 {
		t.Fatalf("cursorCol = %d; want 3", editor.state.cursorCol)
	}
	editor.state.cursorCol = 0
	editor.moveWordForwardsLocked()
	if editor.state.cursorCol != 1 {
		t.Fatalf("forward cursorCol = %d; want 1", editor.state.cursorCol)
	}
}

// isInSlashCommandContext trims the full JS whitespace set.
func TestEditorSlashCommandContextUnicodeWhitespace(t *testing.T) {
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	if !editor.isInSlashCommandContext("\u3000/cmd") {
		t.Fatal("ideographic space before slash should be a slash-command context")
	}
}

// History and submit trim with JS String.trim (U+FEFF is whitespace, U+0085 is
// not), not strings.TrimSpace.
func TestEditorUsesJSTrim(t *testing.T) {
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	editor.AddToHistory("\uFEFF")
	if len(editor.history) != 0 {
		t.Fatalf("U+FEFF should not be recorded: %q", editor.history)
	}
	editor.AddToHistory("\u0085")
	if len(editor.history) != 1 || editor.history[0] != "\u0085" {
		t.Fatalf("U+0085 should be recorded: %q", editor.history)
	}

	submitted := "unset"
	editor.OnSubmit = func(text string) { submitted = text }
	editor.SetText("\uFEFF")
	editor.HandleInput("\r")
	if submitted != "" {
		t.Fatalf("submit of U+FEFF = %q; want empty", submitted)
	}
}
